function mrdiyEl(tag,text,cls){return element(tag,text,cls);}
function mrdiyBtn(text,fn,cls=''){const b=mrdiyEl('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;}
function mrdiyText(v){if(v===null||v===undefined)return'Unknown';if(typeof v==='number')return v.toLocaleString('en',{maximumFractionDigits:3});if(typeof v==='boolean')return v?'Yes':'No';if(Array.isArray(v))return v.map(mrdiyText).join(' · ');if(typeof v==='object'){if('value'in v)return mrdiyText(v.value)+(v.unit?' '+v.unit:'');return Object.entries(v).map(([k,x])=>k.replaceAll('_',' ')+': '+mrdiyText(x)).join('; ');}return String(v);}
