function mrdiyBadge(text){return mrdiyEl('span',text,'mrdiy-badge');}
function mrdiyStatus(text,error=false){const n=$('#mrdiy-status');if(n){n.textContent=text;n.classList.toggle('error',error);}else notice(text,error);}
function mrdiyMode(host,modes=['SYNTHETIC_INTERNAL']){const b=mrdiyEl('div',undefined,'mrdiy-modes');for(const mode of [...new Set(modes)])b.append(mrdiyBadge(mode));host.append(b);}
function mrdiyPanel(title,text){const p=mrdiyEl('section',undefined,'mrdiy-panel');if(title)p.append(mrdiyEl('h3',title));if(text)p.append(mrdiyEl('p',text));return p;}
