function mrdiyContext(){if(!mrdiyUI.active)return;document.body.dataset.mrdiy='true';callRoomContext('MR D.I.Y. Malaysia · synthetic');const updated=$('#workspace-updated');if(updated)updated.textContent='Scenario v0.4.1';}
