async function mrdiyOpen(id,room='organization'){mrdiyUI.selected=id;mrdiyUI.decisionKey=null;mrdiyUI.detail=null;mrdiyUI.analysis=null;mrdiyUI.comparison=null;mrdiyRoute(room);}
writeLocation=function(mode='replace'){mrdiyLegacyWrite(mode);if(mode==='none')return;const u=new URL(location.href);if(mrdiyUI.active){u.searchParams.delete('legacy');if(mrdiyUI.selected&&['decisions','strategy','advisor'].includes(state.view))u.searchParams.set('mrdiy_case',mrdiyUI.selected);else u.searchParams.delete('mrdiy_case');u.searchParams.delete('demo_case');u.searchParams.delete('context_kind');u.searchParams.delete('org_mode');}else u.searchParams.set('legacy','1');if(u.href!==location.href)history.replaceState(null,'',u.href);};
show=function(view,options){mrdiyLegacyShow(view,options);if(mrdiyUI.active){mrdiyContext();if(state.view==='intelligence')mrdiyIntelligence();}};
