 const result=mrdiyEl('p',undefined,'hint');result.setAttribute('role','status');const list=mrdiyEl('div',undefined,'mrdiy-case-grid');function filter(){mrdiyUI.filter.query=q.value;mrdiyUI.filter.state=st.value;mrdiyUI.filter.deep=check.checked;const f=mrdiyUI.filter,words=f.query.toLowerCase().trim().split(/\s+/).filter(Boolean),rows=s.cases.filter(c=>(!f.type||c.case_type===f.type)&&(!f.state||c.state===f.state)&&(!f.deep||c.deep_demo)&&words.every(w=>JSON.stringify({title:c.title,id:c.case_id,refs:c.object_refs,type:mrdiyTypes[c.case_type]}).toLowerCase().includes(w)));result.textContent=rows.length+' of 40 cases · 16 supply / 10 procurement / 8 service / 6 energy';list.replaceChildren(...rows.map(mrdiyCaseCard));if(!rows.length)list.append(mrdiyEl('p','No cases match. Clear a filter to see the complete working set.'));}for(const n of[q,st,check])n.addEventListener(n===q?'input':'change',filter);host.append(result,list);filter();
