  const adaptive=r.aggregate?.adaptive_past_validation,mean=r.aggregate?.mean_28,zero=r.aggregate?.zero;if(!adaptive||!mean||!zero)throw Error('Rolling study summary is unavailable.');
  const pct=n=>Number.isFinite(n)?(n*100).toFixed(2)+'%':'Unknown';
  section.append(mrdiyBadge('EXTERNAL_BENCHMARK'),mrdiyFacts([['folds',r.folds?.length],['seven-day item forecasts',adaptive.weekly_forecasts],['evaluation status','Exploratory retrospective rolling'],['operational validity','Not established for MR D.I.Y.']]));
