 function render(){const pair=all.find(p=>p.package_id===select.value);if(!pair)return;mrdiyEventUI.packageId=pair.package_id;const b=pair.before,a=pair.after;detail.replaceChildren(mrdiyEl('p',a.feasible?'Example feasible plan, not an automatic selection. Viewing does not reserve resources or execute it.':'Blocked plan · inspection only. No resources are reserved and no action is executed.','mrdiy-plan-safety'),mrdiyExpansionTable(['Identical planned actions','Before','After','Change'],[{values:['Constraint feasibility',b.feasible?'Feasible':'Blocked',a.feasible?'Feasible':'Blocked',pair.feasibility_changed?'Changed':'Unchanged']},{values:['Unmet demand (units)',b.score_vector.shortage_units,a.score_vector.shortage_units,pair.delta.shortage_units]},{values:['Known conditional cost (MYR)',b.score_vector.known_conditional_cost_myr,a.score_vector.known_conditional_cost_myr,pair.delta.known_conditional_cost_myr]},{values:['Continuity gap (hours)',b.score_vector.continuity_gap_hours,a.score_vector.continuity_gap_hours,pair.delta.continuity_gap_hours]},{values:['Arrival day (world date = day 0)',b.planned_arrival_day,a.planned_arrival_day,a.planned_arrival_day-b.planned_arrival_day]},{values:['Trade-off frontier',b.pareto_efficient?'On frontier':'Off frontier',a.pareto_efficient?'On frontier':'Off frontier',pair.frontier_changed?'Changed':'Unchanged']}]),mrdiyEl('p','A plan can remain resource-feasible while its shortage or modeled cost increases. Known cost excludes unpriced energy, service and invoice-review consequences.','hint'));if(a.blocked_constraints.length)detail.append(mrdiyEl('p','After replay, blocked by: '+a.blocked_constraints.map(c=>c.constraint).join(', '),'mrdiy-risk-note'));mrdiyEventStress(detail,r,pair);}
