function mrdiyEventStress(host,replay,pair){
 const section=mrdiyEl('details',undefined,'mrdiy-details mrdiy-event-stress');section.append(mrdiyEl('summary','Test this plan under other assumptions'),mrdiyEl('p','Keep this plan fixed while testing six total delay values. Resource feasibility, demand coverage and trade-offs are separate checks.','hint'));host.append(section);
 const result=mrdiyEl('div'),button=mrdiyBtn('Check when this plan stops covering demand',()=>run(false),'quiet-button');button.classList.add('mrdiy-stress-run');section.append(button,result);let pending=false;
 const signature=expanded=>JSON.stringify({event:replay.provenance.event_id,delay:replay.provenance.total_delay_days,basis:mrdiyEventUI.basis,plan:pair.package_id,expanded});
 function display(r){
  result.replaceChildren(mrdiyEl('p',r.points.length+' tested combinations · all other constraints held fixed','mrdiy-event-confirmed'));
  result.append(mrdiyExpansionTable(['Total delay (days)','Demand ×','Unmet units','Hard constraints','Demand covered','Trade-off frontier'],r.points.map(p=>({shortage:p.selected?.shortage_units>0,values:[p.delay_days,p.demand_multiplier,p.selected?.shortage_units,p.selected?.feasible===true?'Feasible':p.selected?.feasible===false?'Blocked':'Unknown',p.selected?.covers_demand===true?'Yes':p.selected?.covers_demand===false?'No':'Unknown',p.selected?.pareto_efficient===true?'On frontier':p.selected?.pareto_efficient===false?'Off frontier':'Unknown']}))));
  const transitions=(r.tested_transitions||[]).filter(t=>t.property==='covers_demand');
  for(const t of transitions)result.append(mrdiyEl('p',(t.axis==='delay_days'?'At demand ×'+t.fixed.demand_multiplier+', demand coverage changes between tested total delays ':'At total delay '+t.fixed.delay_days+' days, demand coverage changes between tested demand multipliers ')+t.from.tested_value+' ('+(t.from.value?'covered':'uncovered')+') and '+t.to.tested_value+' ('+(t.to.value?'covered':'uncovered')+').','hint'));
  if(!transitions.length)result.append(mrdiyEl('p','No coverage transition appears between these tested points. This does not establish a boundary outside the tested range.','hint'));
  result.append(mrdiyEl('p','Discrete what-if checks only. No exact continuous threshold, business probability or automatic plan switch is inferred.','hint'),mrdiyJSONDetails('Tested points, constraints, dominance and frozen inputs',r));
  if(r.grid.demand_multipliers.length===1){const expand=mrdiyBtn('Also vary demand · 30 tested combinations',()=>run(true),'quiet-button');expand.classList.add('mrdiy-stress-expand');result.append(expand);}
 }
 async function run(expanded){
  if(pending||!mrdiyEventIsCurrent()||mrdiyEventUI.result!==replay||mrdiyEventUI.packageId!==pair.package_id)return;pending=true;button.disabled=true;const token=++mrdiyEventUI.stressToken,key=signature(expanded);result.replaceChildren(mrdiyEl('p','Running the bounded '+(expanded?'delay-and-demand':'delay-only')+' checks…','hint'));
  try{const r=await request('/api/mrdiy/event-plan-stress',{...mrdiyEventUI.confirmedRequest,selected_package_id:pair.package_id,include_demand_stress:expanded});if(token!==mrdiyEventUI.stressToken||!mrdiyEventIsCurrent()||mrdiyEventUI.result!==replay||mrdiyEventUI.packageId!==pair.package_id||key!==signature(expanded))return;if(r.status!=='ok')throw Error(mrdiyText(r.missing_inputs||'The selected plan could not be evaluated.'));mrdiyEventUI.stress={key,result:r};display(r);}
  catch(error){if(token!==mrdiyEventUI.stressToken)return;result.replaceChildren(mrdiyEl('p','Plan stress check unavailable: '+error.message+'. The confirmed before/after replay remains available.','mrdiy-risk-note'));}
  finally{pending=false;button.disabled=false;}
 }
 if(mrdiyEventUI.stress&&[signature(false),signature(true)].includes(mrdiyEventUI.stress.key))display(mrdiyEventUI.stress.result);
}

function mrdiyLegacy(){mrdiyUI.active=false;document.body.dataset.mrdiy='false';mrdiyUI.ticket++;callUI.context.kind='organization';callUI.demoId=null;show('organization');let button=$('#mrdiy-return');if(!button){button=mrdiyBtn('MR D.I.Y. demo',()=>{mrdiyUI.active=true;mrdiyUI.selected=null;mrdiyRoute('home');});button.id='mrdiy-return';$('header').append(button);}}
document.addEventListener('click',e=>{if(mrdiyUI.active&&e.target.closest('nav button[data-view=organization]'))mrdiyUI.selected=null;},true);
if(typeof window!=='undefined'&&window.addEventListener)window.addEventListener('popstate',()=>{const u=new URL(location.href);mrdiyUI.active=u.searchParams.get('legacy')!=='1';mrdiyUI.selected=u.searchParams.get('mrdiy_case');document.body.dataset.mrdiy=String(mrdiyUI.active);if(mrdiyUI.active)show(u.searchParams.get('view')||'home',{history:'none'});});
if(mrdiyUI.active){document.body.dataset.mrdiy='true';++callUI.load;callUI.context={kind:'demo',projectId:null};organizationUI.projectId=null;organizationUI.project=null;prototypeUI.caseId=null;const status=mrdiyEl('p');status.id='mrdiy-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');$('#main').prepend(status);show(new URL(location.href).searchParams.get('view')||'home',{history:'replace'});}
